<script lang="ts">
 import type {Project} from './model';import type {ReferenceKind} from './catalog-definitions';import {referenceRows} from './reference-catalogs';import {X,FolderOpen} from '@lucide/svelte';import {translator} from './i18n';import {openReportLookup} from './report-settings';import {catalogs} from './desktop-menu';
 export let project:Project;export let kind:ReferenceKind;export let value='';export let onopen:(kind:ReferenceKind)=>void;
 $:t=translator(project.settings.language);$:rows=referenceRows(project,kind);$:label=rows.find(r=>r.id===value)?.name||value;
 function choose(){openReportLookup({id:crypto.randomUUID(),label:catalogs.find(c=>c.id===kind)?.[project.settings.language]||kind,kind,items:rows.map(r=>({id:r.id,code:r.code,name:r.name})),selected:value?[value]:[],multiple:false,onchoose:ids=>value=ids[0]||''});}
</script>
<div class="reference-picker"><input readonly value={label} aria-label={catalogs.find(c=>c.id===kind)?.[project.settings.language]||kind}/><button type="button" aria-label={t('Выбрать из справочника','Selectează din catalog')} onclick={choose}>…</button><button type="button" aria-label={t('Очистить значение','Șterge valoarea')} onclick={()=>value=''}><X size={15}/></button><button type="button" aria-label={t('Открыть справочник','Deschide catalogul')} onclick={()=>onopen(kind)}><FolderOpen size={15}/></button></div>
<style>.reference-picker{display:flex;min-width:0;gap:6px}.reference-picker>input{flex:1;min-width:0;width:100%;height:36px;box-sizing:border-box}.reference-picker>button{display:grid;place-items:center;flex:none;width:34px;height:36px;box-sizing:border-box;border:1px solid var(--border);background:var(--input);color:var(--text);padding:0}</style>
